using System;
using System.Text;
using MapEdit;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using MonsterEdit.monsters;
using ProjectTower.audio;
using ProjectTower.character;
using ProjectTower.director;
using ProjectTower.game;
using ProjectTower.hud;
using ProjectTower.map;
using ProjectTower.particles;
using ProjectTower.player;
using ProjectTower.texturesheet;

namespace ProjectTower.gamestate;

public class BossToast
{
	public static bool active;

	public static float frame;

	public static RenderTarget2D toastTarg;

	public static bool needsTarg;

	public static Vector2 destVec;

	public static float destZoom;

	public static Vector2[] wisp;

	public static StringBuilder title;

	private static StringBuilder locTitle;

	private static int bossIdx;

	public static bool confirmedOkay;

	public static bool GetNoUpdate()
	{
		if (active && frame < 4f)
		{
			return frame > 1f;
		}
		return false;
	}

	public static void UpdateScroll(CamMgr camMgr)
	{
		QuakeManager.quake = 0f;
		if (frame > 4f)
		{
			float cosProg = Trig.GetCosProg(5f - frame);
			float num = 1f;
			if (frame > 4.5f)
			{
				num = (5f - frame) / 0.5f;
			}
			Vector2 vector = camMgr.originVec + (destVec - camMgr.originVec) * cosProg;
			float num2 = camMgr.origZoom + (destZoom - camMgr.origZoom) * cosProg;
			ScrollManager.scroll += (vector - ScrollManager.scroll) * num;
			ScrollManager.zoom += (num2 - ScrollManager.zoom) * num;
		}
		else if (frame > 1f)
		{
			ScrollManager.scroll = destVec;
			ScrollManager.zoom = destZoom;
		}
		else
		{
			float cosProg2 = Trig.GetCosProg(frame);
			ScrollManager.scroll = camMgr.originVec + (destVec - camMgr.originVec) * cosProg2;
			ScrollManager.zoom = camMgr.origZoom + (destZoom - camMgr.origZoom) * cosProg2;
		}
	}

	public static void Update()
	{
		if (!confirmedOkay)
		{
			if (GameStateManager.coopPlayerIdx > -1)
			{
				Character playerCharacter = CharMgr.GetPlayerCharacter(PlayerMgr.GetCoopPlayer());
				if (playerCharacter.state == 0 && playerCharacter.hp > 0f)
				{
					confirmedOkay = true;
				}
			}
			Character playerCharacter2 = CharMgr.GetPlayerCharacter(PlayerMgr.GetMainPlayer());
			if (playerCharacter2.state == 0 && playerCharacter2.hp > 0f)
			{
				confirmedOkay = true;
			}
			if (MapMgr.map.triggerMgr.GetActiveArenaIdx(playerCharacter2) < 0)
			{
				active = false;
				confirmedOkay = false;
			}
		}
		else
		{
			float num = frame;
			if (frame >= 4f)
			{
				frame -= Game1.frameTime * 0.9f;
			}
			else if (frame > 1f && frame < 4f)
			{
				frame -= Game1.frameTime * 0.615f;
			}
			else
			{
				frame -= Game1.frameTime;
			}
			if (frame < 4f && num >= 4f)
			{
				Sound.PlaySnd("jail");
			}
			if (frame <= 0f)
			{
				active = false;
			}
		}
	}

	public static void Set(int setBossIdx, CamMgr camMgr)
	{
		try
		{
			if (GameStateManager.coopPlayerIdx > -1)
			{
				_ = GameStateManager.splitScreenCoopMode;
			}
			if (wisp == null)
			{
				wisp = new Vector2[32];
			}
			for (int i = 0; i < wisp.Length; i++)
			{
				wisp[i] = Rand.GetRandomVec2(0f, 640f, 0f, 360f);
			}
			needsTarg = true;
			frame = 5f;
			active = true;
			camMgr.originVec = ScrollManager.scroll;
			camMgr.origZoom = ScrollManager.zoom;
			bossIdx = setBossIdx;
			confirmedOkay = false;
			Character character = CharMgr.character[bossIdx];
			MonsterDef monsterDef = MonsterCatalog.catalog[character.monsterIdx];
			float num = (monsterDef.giant ? character.rects.height : monsterDef.boxHeight);
			destVec = character.loc;
			switch (monsterDef.defIdx)
			{
			case 29:
				num = 1200f;
				break;
			case 21:
				num = 400f;
				break;
			}
			float hdFactor = ScrollManager.GetHdFactor();
			num *= 1f;
			destVec.Y -= num / 2f;
			destZoom = (-4f - num * 0.01f) * hdFactor;
			character.charAI.timeSinceAttack = -30f;
			character.anim.SetAnimation("activate");
			title = new StringBuilder(monsterDef.title[0]);
			locTitle = new StringBuilder("(" + monsterDef.title[Game1.language] + ")");
			PlayerMgr.GetMainPlayer().latestBossStr = monsterDef.name;
			if (GameStateManager.coopPlayerIdx > -1)
			{
				PlayerMgr.GetCoopPlayer().latestBossStr = monsterDef.name;
			}
		}
		catch (Exception)
		{
		}
	}

	public static void Draw()
	{
		float hdFactor = ScrollManager.GetHdFactor();
		if (needsTarg || toastTarg == null)
		{
			return;
		}
		if (frame <= 1f && frame > 0.5f)
		{
			SpriteTools.BeginAdditive();
			SpriteTools.sprite.Draw(toastTarg, ScrollManager.screenSize / 2f, new Rectangle(0, 0, toastTarg.Width, toastTarg.Height), new Color(1f, 1f, 1f, (frame - 0.5f) * 2f), (4f - frame) * 0.01f, new Vector2(toastTarg.Width, toastTarg.Height) / 2f, 1.1f + (5f - frame) * 0.03f, SpriteEffects.None, 1f);
			SpriteTools.End();
		}
		if (frame < 4f && frame > 1f)
		{
			GameDraw.mainEffect.Parameters["tR"].SetValue(1f);
			GameDraw.mainEffect.Parameters["tG"].SetValue(0.95f);
			GameDraw.mainEffect.Parameters["tB"].SetValue(0.9f);
			GameDraw.mainEffect.Parameters["bR"].SetValue(0.8f);
			GameDraw.mainEffect.Parameters["bG"].SetValue(0.75f);
			GameDraw.mainEffect.Parameters["bB"].SetValue(0.7f);
			GameDraw.mainEffect.Parameters["brite"].SetValue(1.4f);
			GameDraw.mainEffect.Parameters["burnR"].SetValue(-1.4f);
			GameDraw.mainEffect.Parameters["burnG"].SetValue(-1.2f);
			GameDraw.mainEffect.Parameters["burnB"].SetValue(-1f);
			GameDraw.mainEffect.Parameters["gamma"].SetValue(-0.1f);
			float num = 1f;
			if (frame < 1.5f)
			{
				num += Rand.GetRandomFloat(0f, 1.5f - frame) * 0.1f;
			}
			GameDraw.mainEffect.Parameters["CloudsTexture"].SetValue(LayerTintCatalog.parchmentTex);
			GameDraw.mainEffect.Parameters["SampleTexture"].SetValue(toastTarg);
			SpriteTools.BeginAlpha(GameDraw.mainEffect);
			SpriteTools.sprite.Draw(toastTarg, ScrollManager.screenSize / 2f, new Rectangle(0, 0, toastTarg.Width, toastTarg.Height), new Color(1f, 1f, 1f, 1f), (4f - frame) * 0.01f, new Vector2(toastTarg.Width, toastTarg.Height) / 2f, (1.1f + (5f - frame) * 0.03f) * num, SpriteEffects.None, 1f);
			SpriteTools.End();
			SpriteTools.BeginSubtractive();
