using System;
using MapEdit;
using Microsoft.Xna.Framework;
using ProjectTower.audio;
using ProjectTower.particles;
using ProjectTower.player;
using ProjectTower.texturesheet;

namespace ProjectTower.character;

public class CharTorch
{
	public struct TorchNode
	{
		public Vector2 loc;

		public Vector2 traj;

		public int idx;

		public float frame;

		public bool active;

		public void CopyFrom(TorchNode node)
		{
			loc = node.loc;
			traj = node.traj;
			frame = node.frame;
			idx = node.idx;
		}

		public void Draw(TorchNode node, float r, float g, float b)
		{
			if (frame > 0.1f)
			{
				Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc((loc + node.loc) / 2f, 0), idx, new Vector2((loc - node.loc).Length() * 0.0115f, 0.25f * (frame + 0.4f)) * ScrollManager.cannedDepth[0], Trig.GetAngle(loc, node.loc), r, g, b, frame * 2f);
			}
		}

		internal void Init(Vector2 loc)
		{
			this.loc = loc;
			idx = Rand.GetRandomInt(5, 9);
			traj = Rand.GetRandomVec2(-200f, 300f, -300f, -100f);
			if (Rand.CoinToss(0.1f))
			{
				traj += Rand.GetRandomVec2(-1f, 1f, -1f, 1f) * 1000f;
			}
			frame = Rand.GetRandomFloat(0.35f, 0.4f);
		}

		internal void Update()
		{
			if (frame > 0f)
			{
				frame -= Game1.frameTime;
				loc += traj * Game1.frameTime;
			}
		}
	}

	public bool inited;

	public const int MAX_NODES = 16;

	public TorchNode[] node;

	private const float MAX_FRAME = 0.05f;

	private float frame;

	public bool active;

	private float uberFrame;

	private bool addParticle;

	private Character c;

	public CharTorch(Character c)
	{
		node = new TorchNode[16];
		this.c = c;
	}

	public void Draw()
	{
		if (!inited)
		{
			return;
		}
		float r = 1f;
		float g = 1f;
		float b = 1f;
		if (c.playerIdx > -1)
		{
			Player player = c.GetPlayer();
			if (player.runes[4] && player.runes[5])
			{
				g = 0.25f;
			}
			else if (player.runes[4])
			{
				g = 0.5f;
				b = 0.5f;
			}
			else if (player.runes[5])
			{
				r = 0.5f;
				g = 0.6f;
			}
		}
		for (int i = 1; i < node.Length; i++)
		{
			node[i].Draw(node[i - 1], r, g, b);
		}
		Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(node[0].loc, 0), node[0].idx, new Vector2(1f, 1f) * 0.2f * ScrollManager.cannedDepth[0], node[0].frame * 1f, r, g, b, 1f);
	}

	public void Update()
	{
		frame -= Game1.frameTime;
		if (active)
		{
			addParticle = false;
			float num = uberFrame;
			uberFrame += Game1.frameTime;
			if (uberFrame > 1f)
			{
				uberFrame--;
			}
			if ((int)(num * 60f) != (int)(uberFrame * 60f))
			{
				addParticle = true;
			}
		}
		for (int i = 0; i < node.Length; i++)
		{
			node[i].Update();
		}
		for (int j = 1; j < node.Length - 1; j++)
		{
			if ((node[j - 1].loc + node[j + 1].loc).LengthSquared() > 500000f)
			{
				Vector2 vector = (node[j - 1].loc + node[j + 1].loc) / 2f;
				node[j].loc += (vector - node[j].loc) * Game1.frameTime * 20f;
			}
		}
		if (frame < -1f)
		{
			active = false;
		}
	}

	public void Set(Vector2 loc)
	{
		active = true;
		node[0].loc = loc;
		if (addParticle && c.playerIdx > -1)
		{
			Player player = c.GetPlayer();
			for (int i = 4; i < 8; i++)
			{
				if (player.runes[5] && Rand.CoinToss(0.1f))
				{
					Rand.GetRandomFloat(0f, (float)Math.PI * 2f);
					Rand.GetRandomFloat(0f, 100f);
					ParticleManager.AddAdditiveParticle(141, node[i].loc, node[i].traj * 0.1f, Rand.GetRandomFloat(0.01f, 0.2f), 0f, 1, c.ID);
				}
				if (player.runes[4] && Rand.CoinToss(0.1f))
				{
					Rand.GetRandomFloat(0f, (float)Math.PI * 2f);
					Rand.GetRandomFloat(0f, 100f);
					ParticleManager.AddAdditiveParticle(141, node[i].loc, node[i].traj * 0.1f, Rand.GetRandomFloat(0.01f, 0.2f), 0f, 0, c.ID);
				}
			}
		}
		Sound.PlaySpre(3, loc, 0);
		if (frame <= 0f)
		{
			frame = 0.05f;
			for (int num = 15; num > 0; num--)
			{
				node[num].CopyFrom(node[num - 1]);
			}
			node[0].Init(loc);
			if (c.buffs.GetUpsideDown())
			{
				node[0].traj.Y *= -1f;
			}
		}
		if (!inited)
		{
			for (int j = 1; j < node.Length; j++)
			{
				node[j].loc = loc;
				node[j].traj = Rand.GetRandomVec2(-1f, 1f, -1f, 1f) * 1000f;
			}
			inited = true;
		}
	}
}

using LootEdit.loot;
