namespace ProjectTower.gameservices;

public class PropChar
{
	public Vector2 loc;

	public int face;

	public int anim;

	public const float FRAME_TOTAL = 23.5f;

	public float frame;

	public int ID;

	public int pcdIdx = -1;

	public string name;

	public PropChar(int ID)
	{
		this.ID = ID;
	}

	public void Init(string name, string equipment)
	{
		this.name = name;
		pcdIdx = -1;
		for (int i = 0; i < 8; i++)
		{
			if (PropCharMgr.propCharDraw[i].pcIdx == -1)
			{
				pcdIdx = i;
				break;
			}
		}
		if (pcdIdx > -1)
		{
			PropCharDraw propCharDraw = PropCharMgr.propCharDraw[pcdIdx];
			propCharDraw.pcIdx = ID;
			propCharDraw.character.equipment.InitFromString(equipment);
			if (propCharDraw.character.equipment.loadout[0, 1].catalogIdx >= 128 && propCharDraw.character.equipment.loadout[0, 1].catalogIdx - 128 < LootCatalog.category[0].loot.Length && LootCatalog.category[0].loot[propCharDraw.character.equipment.loadout[0, 1].catalogIdx - 128].type == 15)
			{
				propCharDraw.character.equipment.loadout[0, 1].catalogIdx = -1;
			}
			propCharDraw.character.anim.anim = anim;
			propCharDraw.character.anim.frame = 0f;
			propCharDraw.character.anim.key = 0;
			frame = 23.5f;
		}
	}

	internal void Update()
	{
		if (pcdIdx <= -1)
		{
			return;
		}
		PropCharMgr.propCharDraw[pcdIdx].Update(this);
		_ = frame;
		frame -= Game1.frameTime;
		if (frame > 3f && frame < 11.75f)
		{
			Vector2 screenLoc = ScrollManager.GetScreenLoc(loc, 0);
			if (screenLoc.X > 0f && screenLoc.Y > 0f && screenLoc.X < ScrollManager.screenSize.X && screenLoc.Y < ScrollManager.screenSize.Y)
			{
				frame = 11.75f;
			}
		}
		if (frame <= 0f)
		{
			PropCharMgr.propCharDraw[pcdIdx].pcIdx = -1;
			pcdIdx = -1;
		}
	}

	internal bool Draw()
	{
		if (pcdIdx > -1)
		{
			return PropCharMgr.propCharDraw[pcdIdx].Draw(this);
		}
		return false;
	}

	internal void InitFromSeg(Seg seg, int animIdx)
	{
		loc = seg.loc;
		face = seg.intFlag;
		anim = animIdx;
	}
}
using MapEdit;
