namespace ProjectTower.gameservices;

public class PropCharDraw
{
	public Character character;

	public int pcIdx = -1;

	public int ID;

	public PropCharDraw(int ID)
	{
		this.ID = ID;
		character = new Character(0);
		character.Init("deadprop", default, 0, -1, 0);
	}

	internal void Update(PropChar pc)
	{
		character.anim.Update(Game1.frameTime, sequenceChar: false);
		if (character.draw.charCloth != null)
		{
			for (int i = 0; i < character.draw.charCloth.Length; i++)
			{
				character.draw.charCloth[i].Update();
			}
		}
	}

	internal bool Draw(PropChar pc)
	{
		float num = 1f;
		if (pc.frame > 22.5f)
		{
			num = 23.5f - pc.frame;
		}
		if (pc.frame < 1f)
		{
			num = pc.frame;
		}
		character.spawnin = 1f - num;
		character.draw.consumableIdx = 0;
		CharDef charDef = CharDefMgr.charDefList[MonsterCatalog.catalog[character.monsterIdx].defIdx];
		int num2 = 0;
		character.loc = pc.loc;
		Vector2 screenLoc = ScrollManager.GetScreenLoc(pc.loc, 0);
		if (screenLoc.X < -100f || screenLoc.X > ScrollManager.screenSize.X + 100f || screenLoc.Y < -100f || screenLoc.Y > ScrollManager.screenSize.Y + 100f)
		{
			return false;
		}
		Animation animation = charDef.animation[character.anim.anim];
		if (character.anim.key < 0 || character.anim.key >= animation.keyFrame.Length)
		{
			character.anim.key = 0;
		}
		if (animation.keyFrame[character.anim.key].lerp)
		{
			num2 = animation.keyFrame[character.anim.key].frameRef;
			if (num2 < 0)
			{
				num2 = 0;
			}
			int num3 = character.anim.key + 1;
			if (num3 >= animation.keyFrame.Length)
			{
				num3 = 0;
			}
			character.draw.Draw(charDef, ScrollManager.GetScreenLoc(pc.loc, 0), pc.face, ScrollManager.cannedDepth[0] * 1f, num2, animation.keyFrame[num3].frameRef, actorDraw: false, -1f, tint: false, saltTint: false, dyingBossMode: false);
		}
		else
		{
			num2 = animation.keyFrame[character.anim.key].frameRef;
			if (num2 < 0)
			{
				num2 = 0;
			}
			character.draw.Draw(charDef, ScrollManager.GetScreenLoc(pc.loc, 0), pc.face, ScrollManager.cannedDepth[0] * 1f, num2, -1, actorDraw: false, -1f, tint: false, saltTint: false, dyingBossMode: false);
		}
		return true;
	}
}
using MapEdit;
