namespace ProjectTower.gameservices;

internal class PropCharMgr
{
	private struct PropCharDataQueueItem(Vector2 loc, string author, string equipment)
	{
		public Vector2 loc = loc;

		public string author = author;

		public string equipment = equipment;

		public void CopyFrom(PropCharDataQueueItem queueItem)
		{
			loc = queueItem.loc;
			author = queueItem.author;
			equipment = queueItem.equipment;
		}
	}

	public static PropChar[] propChar;

	public static PropCharDraw[] propCharDraw;

	public const int TOTAL_PROP_CHARS = 64;

	public const int TOTAL_PROP_CHAR_DRAWS = 8;

	public static int totalPropChars;

	public const int MSG_AUTHOR = 0;

	public const int MSG_EQUIPMENT = 1;

	public const int MSG_X = 2;

	public const int MSG_Y = 3;

	private static PropCharDataQueueItem[] propCharDataQueueItem;

	private static int totalPropCharDataQueueItems;

	private const int TOTAL_PROP_CHAR_DATA_QUEUE_ITEMS = 32;

	public static void AddPropCharDataQueueItem(Vector2 loc, string author, string equipment)
	{
		if (totalPropCharDataQueueItems < 32)
		{
			for (int num = totalPropCharDataQueueItems; num > 0; num--)
			{
				propCharDataQueueItem[num].CopyFrom(propCharDataQueueItem[num - 1]);
			}
			totalPropCharDataQueueItems++;
			propCharDataQueueItem[0] = new PropCharDataQueueItem(loc, author, equipment);
		}
	}

	public static void Init()
	{
		propChar = new PropChar[64];
		propCharDraw = new PropCharDraw[8];
		propCharDataQueueItem = new PropCharDataQueueItem[32];
		for (int i = 0; i < 64; i++)
		{
			propChar[i] = new PropChar(i);
		}
		for (int j = 0; j < 8; j++)
		{
			propCharDraw[j] = new PropCharDraw(j);
		}
	}

	public static void SetPropChar(string name, Vector2 loc, string equipment)
	{
		AddPropCharDataQueueItem(loc, name, equipment);
	}

	internal static void AddPropChar(Seg seg)
	{
		if (seg.strFlag != null && seg.strFlag.StartsWith("deadprop"))
		{
			string[] array = seg.strFlag.Split(' ');
			if (array.Length > 1)
			{
				string animation = array[1].Split('\r')[0];
				propCharDraw[0].character.anim.SetAnimation(animation);
				int anim = propCharDraw[0].character.anim.anim;
				_ = CharDefMgr.charDefList[MonsterCatalog.catalog[propCharDraw[0].character.monsterIdx].defIdx];
				propChar[totalPropChars].InitFromSeg(seg, anim);
				totalPropChars++;
			}
		}
	}

	internal static void Update()
	{
		if (totalPropCharDataQueueItems > 0)
		{
			bool flag = false;
			for (int i = 0; i < totalPropCharDataQueueItems; i++)
			{
				for (int j = 0; j < totalPropChars; j++)
				{
					if (propChar[j].pcdIdx >= 0)
					{
						continue;
					}
					Vector2 screenLoc = ScrollManager.GetScreenLoc(propChar[j].loc, 0);
					if (screenLoc.X < -100f || screenLoc.X > ScrollManager.screenSize.X + 100f || screenLoc.Y < -100f || screenLoc.Y > ScrollManager.screenSize.Y + 100f)
					{
						continue;
					}
					bool flag2 = false;
					for (int k = 0; k < totalPropChars; k++)
					{
						if (propChar[k].pcdIdx > -1 && propChar[k].name == propCharDataQueueItem[i].author && (propChar[k].loc - propChar[j].loc).LengthSquared() < 100000f)
						{
							flag2 = true;
							break;
						}
					}
					if (flag2)
					{
						continue;
					}
					propChar[j].Init(propCharDataQueueItem[i].author, propCharDataQueueItem[i].equipment);
					for (int l = i; l < totalPropCharDataQueueItems; l++)
					{
						if (l < totalPropCharDataQueueItems - 1)
						{
							propCharDataQueueItem[l].CopyFrom(propCharDataQueueItem[l + 1]);
						}
					}
					totalPropCharDataQueueItems--;
					flag = true;
					break;
				}
				if (flag)
				{
					break;
				}
			}
		}
		for (int m = 0; m < totalPropChars; m++)
		{
			propChar[m].Update();
		}
	}

	internal static void Draw()
	{
		if (!PlayerMgr.GetOnlineCapable())
		{
			return;
		}
		for (int i = 0; i < totalPropChars; i++)
		{
			if (!propChar[i].Draw() && propChar[i].pcdIdx > -1 && totalPropCharDataQueueItems > 16)
			{
				propChar[i].pcdIdx = -1;
			}
		}
	}

	internal static void Reset()
	{
		totalPropChars = 0;
	}
}

using Microsoft.Xna.Framework;
using ProjectTower.character;
using ProjectTower.gameservices.charSequence;
using ProjectTower.particles;
using ProjectTower.player;
using ProjectTower.texturesheet;
using SmashEdit.smashables;

namespace ProjectTower.smash;

public class SmashMgr
{
	public static int smashIdx;

	public static int smashBitIdx;

	public static SmashCatalog catalog;

	public static Smashable[] smashable;

	public const int TOTAL_SMASHABLES = 256;

	public static void Init()
	{
		catalog = new SmashCatalog();
		catalog.Read("smash/data/master.zsx");
		smashIdx = Textures.GetTextureIdx("smashables");
		smashBitIdx = Textures.GetTextureIdx("smashbits");
		smashable = new Smashable[256];
		for (int i = 0; i < smashable.Length; i++)
		{
			smashable[i] = new Smashable(i);
		}
	}

	public static void Reset()
	{
		for (int i = 0; i < smashable.Length; i++)
		{
			if (smashable[i].seqIdx > -1 && CharSequenceMgr.charSequence[smashable[i].seqIdx].smashIdx == i)
			{
				CharSequenceMgr.charSequence[smashable[i].seqIdx].phase = 0;
			}
			smashable[i].exists = false;
		}
	}

	public static int AddSmashable(Vector2 loc, int defIdx)
	{
		for (int i = 0; i < smashable.Length; i++)
		{
			if (!smashable[i].exists)
			{
				if (smashable[i].Init(loc, defIdx))
				{
					return i;
				}
				return -1;
			}
		}
		return -1;
	}

	internal static void DoHit(Vector2 loc, Vector2 traj)
	{
		for (int i = 0; i < smashable.Length; i++)
		{
			if (smashable[i].exists && smashable[i].drawAlpha >= 1f && smashable[i].rect.Contains((int)loc.X, (int)loc.Y))
			{
				smashable[i].Destroy(traj);
				break;
			}
		}
	}

	internal static void Draw()
	{
		bool onlineCapable = PlayerMgr.GetOnlineCapable();
		for (int i = 0; i < smashable.Length; i++)
		{
			if (smashable[i].exists)
			{
				smashable[i].Draw(onlineCapable);
			}
		}
	}

	internal static void DoHit(Particle p)
	{
		Vector2 traj = default;
		if (p.type == 5)
		{
			if (p.owner > -1)
			{
				traj.X = ((float)CharMgr.character[p.owner].face - 0.5f) * 200f;
			}
		}
		else
		{
			traj = p.traj * 0.1f;
		}
		DoHit(p.loc, traj);
	}
}
using MapEdit;
using Microsoft.Xna.Framework;
using ProjectTower.audio;
using ProjectTower.gameservices.charSequence;
using ProjectTower.particles;
using ProjectTower.texturesheet;
using SmashEdit.smashables;

namespace ProjectTower.smash;

public class Smashable
{
	public Vector2 loc;

	public int defIdx;

	private int ID;

	public bool exists;

	public Rectangle rect;

	public const int SMASH_SND_NONE = -1;

	public const int SMASH_SND_WOOD = 0;

	public const int SMASH_SND_METAL = 1;

	public const int SMASH_SND_POTTERY = 2;

	public const int SMASH_SND_ROCK = 3;

	private const int MIN_HEIGHT = 90;

	public int seqIdx;

	public float drawAlpha;

	public Smashable(int ID)
	{
		this.ID = ID;
	}

	public bool Init(Vector2 loc, int defIdx)
	{
		this.loc = loc;
		this.defIdx = defIdx;
		exists = true;
		seqIdx = -1;
		try
		{
			Vector2 vector = SmashMgr.catalog.smash[defIdx].size * 2f;
			rect = new Rectangle((int)(loc.X - vector.X / 2f), (int)(loc.Y - vector.Y), (int)vector.X, (int)vector.Y);
			drawAlpha = 1f;
			if (rect.Height < 90)
			{
				int num = 90 - rect.Height;
				rect.Height += num;
				rect.Y -= num;
			}
			return true;
		}
		catch
		{
			exists = false;
		}
		return false;
	}

	public void Draw(bool onlineCapable)
	{
		if (!(loc.X > ScrollManager.tL.X - 100f) || !(loc.X < ScrollManager.bR.X + 100f) || !(loc.Y > ScrollManager.tL.Y - 200f) || !(loc.Y < ScrollManager.bR.Y + 200f))
		{
			return;
		}
		SmashDef smashDef = SmashMgr.catalog.smash[defIdx];
		Textures.tex[SmashMgr.smashIdx].Draw(ScrollManager.GetScreenLoc(loc, 0), smashDef.image, new Vector2(1f, 1f) * ScrollManager.cannedDepth[0], 0f, 1f, 1f, 1f, drawAlpha);
		if (seqIdx <= -1)
		{
			return;
		}
		if (onlineCapable)
		{
			if (drawAlpha < 1f)
			{
				drawAlpha += 1f / 60f;
				if (drawAlpha > 1f)
				{
					drawAlpha = 1f;
				}
			}
		}
		else if (drawAlpha > 0f)
		{
			drawAlpha -= 1f / 60f;
			if (drawAlpha < 0f)
			{
				drawAlpha = 0f;
			}
		}
		else if (!onlineCapable)
		{
			exists = false;
		}
	}

	public void Destroy(Vector2 traj)
	{
		QuakeManager.SetQuake(0.5f, loc);
		SmashDef smashDef = SmashMgr.catalog.smash[defIdx];
		int owner = -1;
		for (int i = 0; i < smashDef.totalSpawns; i++)
		{
			switch (smashDef.spawn[i].type)
			{
			case 5:
				Sound.Play3DSound("wood", loc, 0);
				owner = 0;
				break;
			case 6:
				Sound.Play3DSound("pottery", loc, 0);
				owner = 2;
				break;
			case 7:
				Sound.Play3DSound("rock", loc, 0);
				owner = 3;
				break;
			case 8:
				Sound.Play3DSound("junk", loc, 0);
				owner = 1;
				break;
			}
		}
		if (Rand.CoinToss(0.5f))
		{
			int randomInt = Rand.GetRandomInt(1, 10);
			int randomInt2 = Rand.GetRandomInt(0, 4);
			for (int j = 0; j < randomInt2; j++)
			{
				ParticleManager.AddAdditiveParticle(112, loc + Rand.GetRandomVec2(-20f, 20f, -50f, -40f), default, Rand.GetRandomFloat(0f, 0.5f), 0f, randomInt / randomInt2 + 1, -1);
			}
		}
		if (seqIdx > -1 && CharSequenceMgr.charSequence[seqIdx].smashIdx == ID)
		{
			CharSequenceMgr.charSequence[seqIdx].smashIdx = -1;
		}
		for (int k = 0; k < smashDef.totalSpawns; k++)
		{
			for (int l = 0; l < smashDef.spawn[k].count; l++)
			{
				Vector2 vector = smashDef.spawn[k].loc + Rand.GetRandomVec2(0f - smashDef.spawn[k].locRange.X, smashDef.spawn[k].locRange.X, 0f - smashDef.spawn[k].locRange.Y, smashDef.spawn[k].locRange.Y);
				Vector2 vector2 = smashDef.spawn[k].traj + Rand.GetRandomVec2(0f - smashDef.spawn[k].trajRange.X, smashDef.spawn[k].trajRange.X, 0f - smashDef.spawn[k].trajRange.Y, smashDef.spawn[k].trajRange.Y);
				switch (smashDef.spawn[k].type)
				{
				case 0:
				{
					int num = ParticleManager.AddBackNormalParticle(18, loc + vector, vector2 + Rand.GetRandomFloat(0f, 1f) * traj, 1f, smashDef.spawn[k].rotation, smashDef.spawn[k].idx, owner);
					if (Rand.CoinToss(0.2f) && num > -1)
					{
						Particle obj = ParticleManager.particleList[1].particle[num];
						obj.rDir = Rand.GetRandomFloat(-50f, 50f);
						obj.traj *= Rand.GetRandomFloat(1f, 3f);
						obj.traj.Y -= Rand.GetRandomFloat(100f, 500f);
					}
					break;
				}
				case 1:
					ParticleManager.AddBackNormalParticle(19, loc + vector, vector2 + Rand.GetRandomFloat(0f, 0.1f) * traj, smashDef.spawn[k].rotation, 0f, 0, -1);
					break;
				case 4:
					ParticleManager.AddBackNormalParticle(20, loc + vector, vector2 + Rand.GetRandomFloat(0f, 0.5f) * traj, smashDef.spawn[k].rotation, 0f, 0, -1);
					break;
				}
			}
		}
		exists = false;
	}
}

