using System.IO;
using Microsoft.Xna.Framework;
using SheetEdit.TextureSheet;

namespace SmashEdit.smashables;

public class SmashDef
{
	public struct SmashSpawn
	{
		public Vector2 loc;

		public Vector2 locRange;

		public Vector2 traj;

		public Vector2 trajRange;

		public const int TYPE_SMASHBIT = 0;

		public const int TYPE_SMOKE = 1;

		public const int TYPE_CANDLE = 2;

		public const int TYPE_FIREPLACE = 3;

		public const int TYPE_DUST = 4;

		public const int TYPE_WOOD_SND = 5;

		public const int TYPE_POTTERY_SND = 6;

		public const int TYPE_STONE_SND = 7;

		public const int TYPE_METAL_SND = 8;

		public const int PARTICLE_IDX_NORMAL = 0;

		public const int PARTICLE_IDX_10HP = 1;

		public const int PARTICLE_IDX_20HP = 2;

		public const int PARTICLE_IDX_90HP = 3;

		public int type;

		public int idx;

		public int count;

		public float rotation;

		public void Write(BinaryWriter writer)
		{
			writer.Write(loc.X);
			writer.Write(loc.Y);
			writer.Write(locRange.X);
			writer.Write(locRange.Y);
			writer.Write(traj.X);
			writer.Write(traj.Y);
			writer.Write(trajRange.X);
			writer.Write(trajRange.Y);
			writer.Write(type);
			writer.Write(idx);
			writer.Write(count);
			writer.Write(rotation);
		}

		public void Read(BinaryReader reader)
		{
			loc = new Vector2(reader.ReadSingle(), reader.ReadSingle());
			locRange = new Vector2(reader.ReadSingle(), reader.ReadSingle());
			traj = new Vector2(reader.ReadSingle(), reader.ReadSingle());
			trajRange = new Vector2(reader.ReadSingle(), reader.ReadSingle());
			type = reader.ReadInt32();
			idx = reader.ReadInt32();
			count = reader.ReadInt32();
			if (count < 1)
			{
				count = 1;
			}
			rotation = reader.ReadSingle();
		}

		internal void CopyFrom(SmashSpawn smashSpawn)
		{
			loc = smashSpawn.loc;
			locRange = smashSpawn.locRange;
			traj = smashSpawn.traj;
			trajRange = smashSpawn.trajRange;
			type = smashSpawn.type;
			idx = smashSpawn.idx;
			count = smashSpawn.count;
			rotation = smashSpawn.rotation;
		}
	}

	public string name;

	public int image;

	public Vector2 size;

	public const int TOTAL_SPAWNS = 32;

	public SmashSpawn[] spawn;

	public int totalSpawns;

	public SmashDef()
	{
		spawn = new SmashSpawn[32];
		for (int i = 0; i < spawn.Length; i++)
		{
			spawn[i].count = 1;
		}
	}

	public void CopyFrom(SmashDef other)
	{
		name = other.name;
		image = other.image;
		size = other.size;
		totalSpawns = other.totalSpawns;
		for (int i = 0; i < spawn.Length; i++)
		{
			spawn[i].CopyFrom(other.spawn[i]);
		}
	}

	public void Draw(Vector2 loc, float scale, XTexture xtex, float hitFrame, float brite)
	{
		xtex.Draw(loc, image % 64, new Vector2(1f + hitFrame * 0.5f, 1f - hitFrame * 0.5f) * scale, 0f, brite, brite, brite, 1f);
	}

	public void Write(BinaryWriter writer)
	{
		writer.Write(name);
		writer.Write(image);
		writer.Write(size.X);
		writer.Write(size.Y);
		writer.Write(totalSpawns);
		for (int i = 0; i < totalSpawns; i++)
		{
			spawn[i].Write(writer);
		}
	}

	public void Read(BinaryReader reader)
	{
		name = reader.ReadString();
		image = reader.ReadInt32();
		size = new Vector2(reader.ReadSingle(), reader.ReadSingle());
		totalSpawns = reader.ReadInt32();
		for (int i = 0; i < totalSpawns; i++)
		{
			spawn[i].Read(reader);
		}
	}
}
